import{_ as l,l as r,o as a,c,v as t,p as o,x as i,d,i as p,S as n}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"cpuidle 与 C-state","description":"","frontmatter":{"title":"cpuidle 与 C-state","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cpuidle-cstate.md","filePath":"cs/cpuidle-cstate.md","lastUpdated":1789023840000}'),u={name:"cs/cpuidle-cstate.md"};function h(_,e,m,C,E,f){const s=r("Mermaid");return a(),c("div",null,[e[1]||(e[1]=t('<h1 id="cpuidle-与-c-state" tabindex="-1">cpuidle 与 C-state <a class="header-anchor" href="#cpuidle-与-c-state" aria-label="Permalink to &quot;cpuidle 与 C-state&quot;">​</a></h1><div class="epigraph"><p>C-state 越深越省电，退出延迟越大；cpuidle 根据预计空闲时间选档，避免刚睡就被包打断。</p><footer>—— 据 Linux cpuidle 文档；ACPI C-state；[NAPI](/cs/napi) 与 [轮询 I/O](/cs/io-polling) 为忙碌对照</footer></div><p><a href="/cs/cpufreq-governor">cpufreq</a> 管忙时频率。核 idle 时管 <strong>睡多深</strong>。缺口是 cpuidle：菜单 governor、与中断的博弈。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>poll 路径（DPDK、IOPOLL）故意不进 C-state。普通服务器：idle → 选 C1/C6…。预计空闲来自调度器（下一个 tick 或 hrtimer）。缺口：错估则 exit 延迟伤害 <a href="/cs/latency-measurement">cyclictest</a>；nohz 后课改「下一个 tick」。本课不把每个 CPU 的 residencies 表抄来。</p><p><span class="marginnote">tick 会阻止最深 C-state。irq 亲和把打断集中到部分核，让别的核能睡。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>cpuidle_enter</code>：查预测 → 选 state → <code>mwait</code>/WFI。唤醒：中断，记 residency。对照 EAS：忙时选核选频，闲时选 C。对照 <a href="/cs/zswap">zswap</a>：一个用 CPU 换内存，一个用延迟换焦耳。</p>',8)),(a(),o(n,null,{default:i(()=>[p(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20IDLE%5B%22%E6%97%A0%E4%BB%BB%E5%8A%A1%22%5D%20--%3E%20PRED%5B%22%E9%A2%84%E8%AE%A1%E7%A9%BA%E9%97%B2%E6%97%B6%E9%95%BF%22%5D%0A%20%20PRED%20--%3E%20C%5B%22%E9%80%89%20C-state%22%5D%0A%20%20IRQ%5B%22%E4%B8%AD%E6%96%AD%22%5D%20--%3E%20EXIT%5B%22%E4%BB%98%E9%80%80%E5%87%BA%E5%BB%B6%E8%BF%9F%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>cpuidle 把空闲变成分级睡眠，使平均功耗可降，代价是最坏唤醒。RT 系统常限制最深 C。不要写成电池广告。与 <a href="/cs/rss-multiqueue">RSS</a>：包若打到睡眠核，要付 exit。</p><p>错误预测在高 IRQ 率下会振荡，菜单 governor 有修正。</p><p>实现上：预测过深则 wakeup 付长 exit 延迟，cyclictest max 爆炸。poll 忙等的核 residency 为 0。irq 亲和把打断集中，让旁核睡得着。 读法上只引用<a href="/cs/cpufreq-governor">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「调度进阶 / 公平、实时与能耗」课序里，对象是 <strong>cpuidle 与 C-state</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 S-state 睡眠整机——<a href="/cs/suspend-resume">挂起</a> 后课。不保证虚拟机 halt 是真 C-state。下一课关掉周期性 tick：tickless。</p><p>版本字段会变，课序钉的是机制对象「cpuidle 与 C-state」，不是某一主线内核的结构体名。 后课默认：空闲可选深 C-state。无任务时可停时钟中断，下一课 tickless。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>C-state 用退出延迟换功耗。</li><li>cpuidle 按预计空闲选档。</li><li>tickless 是下一课。</li><li>出处：Linux cpuidle；ACPI；Intel idle。</li></ul>',11))])}const P=l(u,[["render",h]]);export{B as __pageData,P as default};
